def normalize_users(rows):
    # Keep insertion order of first-seen IDs while allowing value updates.
    latest = {}
    for row in rows:
        user_id = int(row["id"])
        name = row["name"].strip()
        if name:
            latest[user_id] = name
    return [{"id": user_id, "name": name} for user_id, name in latest.items()]

def deep_merge(base, override):
    """Recursively merge ``override`` into ``base`` and return the result.

    - Dictionaries are merged recursively.
    - Any non-dictionary value in ``override`` (including lists, scalars, None)
      replaces the corresponding value in ``base``.
    - Keys present only in ``base`` are preserved.
    - Neither input is mutated, and the returned structure contains no mutable
      aliases to either input.
    """
    result = {}
    for key, value in base.items():
        if isinstance(value, dict):
            result[key] = {}
        else:
            result[key] = _copy_value(value)
    for key, value in override.items():
        if isinstance(value, dict):
            if isinstance(result.get(key), dict):
                result[key] = deep_merge(result[key], value)
            else:
                result[key] = _copy_dict(value)
        else:
            result[key] = _copy_value(value)
    return result


def _copy_value(value):
    """Return a deep copy of ``value`` (handles dicts, lists, scalars)."""
    if isinstance(value, dict):
        return _copy_dict(value)
    if isinstance(value, list):
        return [_copy_value(item) for item in value]
    return value


def _copy_dict(mapping):
    """Return a deep copy of ``mapping`` as a plain dict."""
    return {key: _copy_value(value) for key, value in mapping.items()}

