def deep_merge(base, override):
    """Recursively merge ``override`` into ``base`` and return the result.

    - Dictionaries are merged recursively.
    - Any non-dictionary value in ``override`` (including lists, scalars, None)
      replaces the corresponding value in ``base``.
    - Keys present only in ``base`` are preserved.
    - Neither input is mutated, and the returned structure contains no mutable
      aliases to either input.
    """
    result = _copy_dict(base)
    for key, value in override.items():
        if isinstance(value, dict):
            existing = result.get(key)
            if isinstance(existing, dict):
                result[key] = deep_merge(existing, value)
            else:
                result[key] = _copy_dict(value)
        else:
            result[key] = _copy_value(value)
    return result


def _copy_value(value):
    """Return a deep copy of ``value`` (handles dicts, lists, sets, scalars)."""
    if isinstance(value, dict):
        return _copy_dict(value)
    if isinstance(value, list):
        return [_copy_value(item) for item in value]
    if isinstance(value, set):
        return set(value)
    return value


def _copy_dict(mapping):
    """Return a deep copy of ``mapping`` as a plain dict."""
    return {key: _copy_value(value) for key, value in mapping.items()}

def retry_delays(max_retries, base_ms=100, cap_ms=5000):
    if max_retries < 0 or base_ms <= 0 or cap_ms <= 0:
        raise ValueError("max_retries must be >= 0 and base_ms/cap_ms must be positive")
    return [min(base_ms * (2 ** attempt), cap_ms) for attempt in range(max_retries)]

SENSITIVE_KEY_MARKERS = ("password", "token", "secret", "api_key")


def _is_sensitive_key(key):
    if not isinstance(key, str):
        return False
    lowered = key.lower()
    return any(marker in lowered for marker in SENSITIVE_KEY_MARKERS)


def redact_secrets(value):
    """Recursively copy dictionaries and lists, replacing values with "***"
    whenever a dictionary key case-insensitively contains password, token,
    secret, or api_key. All other values are preserved and the input is not
    mutated.
    """
    if isinstance(value, dict):
        return {
            key: "***" if _is_sensitive_key(key) else redact_secrets(item)
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [redact_secrets(item) for item in value]
    return value
